74	/// EnumerationMode -- <metadata><mode> (defined|full|full_sampled). Steuert die ENUMERATIONS-BREITE je Phase
75	/// (wie viele OP-Typen gemessen werden); ORTHOGONAL zur Phase (die den Kompositionalen Join = Merge waehlt).
76	enum class EnumerationMode { Defined, Full, FullSampled };
77	
78	/// parse_enumeration_mode -- <metadata><mode>-Token -> EnumerationMode. Unbekannt/leer -> Defined (sicherer Default).
79	[[nodiscard]] inline EnumerationMode parse_enumeration_mode(std::string_view mode) noexcept {
80	    if (mode == "full") return EnumerationMode::Full;
81	    if (mode == "full_sampled") return EnumerationMode::FullSampled;
82	    return EnumerationMode::Defined;
83	}
