95	/// PhaseCompositions<S> -- die realen Katalog-Kompositionen je MergeStrategy (Policy-Based Design, compile-time).
96	/// EE-A ist STETS die CE-SOTA-Baseline (HotComposition, Stufe1_CeOnly); EE-B ist die Phasen-Komposition:
97	///   Stufe1_CeOnly           -> HotComposition                   (Baseline gegen Baseline: erwarteter Tie)
98	///   Stufe2_PrueflingReplace -> HotPrtStufe2ReplaceComposition   (PRT ersetzt den path_compression-Slot)
99	///   Stufe3_FullJoin         -> HotPrtStufe3FullJoinComposition  (non-redundante Union CE + Pruefling)
100	template <MergeStrategy S>
101	struct PhaseCompositions;
102	
103	template <>
104	struct PhaseCompositions<MergeStrategy::Stufe1_CeOnly> {
105	    using EngineA = comp::HotComposition;
106	    using EngineB = comp::HotComposition;
107	};
108	template <>
109	struct PhaseCompositions<MergeStrategy::Stufe2_PrueflingReplace> {
110	    using EngineA = comp::HotComposition;
111	    using EngineB = comp::HotPrtStufe2ReplaceComposition;
112	};
113	template <>
114	struct PhaseCompositions<MergeStrategy::Stufe3_FullJoin> {
115	    using EngineA = comp::HotComposition;
116	    using EngineB = comp::HotPrtStufe3FullJoinComposition;
117	};
