134	/// op_labels_for_mode -- die je-Phase enumerierte OP-Typ-Liste aus dem Profil, gefiltert nach EnumerationMode:
135	///   Defined     = genau der erste deklarierte OP-Typ (1 Permutation je Phase -> stets >= 1 Verdikt je Phase).
136	///   Full        = alle deklarierten OP-Typen.
137	///   FullSampled = jeder zweite (mindestens 1).
138	/// Leeres <op_types> -> Fallback "OP-1" (auch dann >= 1 Permutation je Phase).
139	[[nodiscard]] inline std::vector<std::string> op_labels_for_mode(std::vector<std::string> const& op_types,
140	                                                                 EnumerationMode                 mode) {
141	    std::vector<std::string> const source = op_types.empty() ? std::vector<std::string>{"OP-1"} : op_types;
142	    std::vector<std::string>       out;
143	    switch (mode) {
144	        case EnumerationMode::Defined: out.push_back(source.front()); break;
145	        case EnumerationMode::Full: out = source; break;
146	        case EnumerationMode::FullSampled:
147	            for (std::size_t i = 0; i < source.size(); i += 2) { out.push_back(source[i]); }
148	            break;
149	    }
150	    if (out.empty()) { out.push_back(source.front()); }
151	    return out;
152	}
