209	/// run_experiment_profile -- der reine Antrieb (INC-G): je Phase des validierten Profils die realen Katalog-
210	/// Tiers treiben und in einen MessreiheReport akkumulieren. KEIN Datei-IO (das ist INC-H/execute_messreihe).
211	[[nodiscard]] inline MessreiheReport run_experiment_profile(cx::ExperimentProfile const& profile,
212	                                                            EnumerationMode              mode) {
213	    MessreiheReport report;
214	    auto const      start = std::chrono::steady_clock::now();
215	
216	    cmd::Workload base;
217	    base.record_count    = 2000; // moderat: genug Samples fuer Welch, Test < TIMEOUT (== INC-F-Gate)
218	    base.operation_count = 2000;
219	    base.seed            = 42;
220	
221	    auto const op_labels = op_labels_for_mode(profile.op_types, mode);
222	
223	    report.total_axes       = profile.phases.size();
224	    std::size_t phase_index = 0;
225	    for (auto const& phase : profile.phases) { (void)dispatch_phase(report, phase, op_labels, base, phase_index++); }
226	
227	    report.total_elapsed = std::chrono::steady_clock::now() - start;
228	    return report;
229	}
